figure.artwork:
{
  "intent": {
    "mode": "natural-language | structured",
    "natural-language": { ... },   // Required when mode=NL
    "structured": { ... }            // Required when mode=structured
  }
}

{
  "confirmation-id": "string",
  "resolution": {
    "action": "approve | reject | modify-and-approve | escalate-to-human",
    "modified-params": { ... }  // Required when action=modify-and-approve
  }
}

module ietf-nma-a2u-common {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-common";
  prefix nma-a2u-common;

  organization
    "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "Common types and groupings for NMA A2U interface.

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  typedef autonomy-level {
    type enumeration {
      enum L0 { description "Manual operation"; }
      enum L1 { description "Assisted operation"; }
      enum L2 { description "Partial automation"; }
      enum L3 { description "Conditional automation"; }
      enum L4 { description "High automation"; }
      enum L5 { description "Full automation"; }
    }
    description "Autonomous Network level per TMF IG1230.";
  }

  typedef intent-mode {
    type enumeration {
      enum natural-language {
        description "Intent expressed in natural language text.";
      }
      enum structured {
        description "Intent expressed in structured data.";
      }
    }
    description "Input mode for intent submission.";
  }

  typedef intent-type {
    type enumeration {
      enum CREATE { description "Create a new resource or service."; }
      enum DELETE { description "Delete an existing resource or service."; }
      enum MODIFY { description "Modify an existing resource or service."; }
      enum QUERY { description "Query status or information."; }
      enum REPORT { description "Generate a report."; }
      enum DIAGNOSE { description "Perform diagnosis."; }
    }
    description "Type of structured intent operation.";
  }

  typedef task-state {
    type enumeration {
      enum PENDING { description "Intent received, awaiting processing."; }
      enum ANALYZING { description "Parsing and analyzing intent."; }
      enum AWAITING_CLARIFICATION { description "Need more info from user."; }
      enum PLANNING { description "Generating execution plan."; }
      enum AWAITING_CONFIRMATION { description "Awaiting user confirmation."; }
      enum EXECUTING { description "Executing the plan."; }
      enum COMPLETED { description "Task completed successfully."; }
      enum FAILED { description "Task failed."; }
      enum ABORTED { description "Task aborted by user or system."; }
    }
    description "Unified task lifecycle state.";
  }

  typedef confirmation-type {
    type enumeration {
      enum EXECUTION {
        description "Confirm before executing a plan.";
      }
      enum PARAMETER_CHANGE {
        description "Confirm parameter modifications.";
      }
      enum DESTRUCTIVE_OPERATION {
        description "Confirm destructive operations.";
      }
      enum POLICY_VIOLATION {
        description "Confirm when policy is violated.";
      }
    }
    description "Type of confirmation required.";
  }

  typedef nma-a2u-event-type {
    type enumeration {
      enum intent-received { description "Intent has been received."; }
      enum intent-parsed { description "Intent parsing completed."; }
      enum intent-clarification-required {
        description "Need clarification for intent.";
      }
      enum intent-rejected { description "Intent rejected."; }
      enum plan-generated { description "Execution plan generated."; }
      enum confirmation-required { description "Confirmation needed."; }
      enum step-started { description "A plan step started."; }
      enum step-completed { description "A plan step completed."; }
      enum step-failed { description "A plan step failed."; }
      enum task-completed { description "Task completed."; }
      enum task-failed { description "Task failed."; }
      enum task-suspended { description "Task suspended."; }
    }
    description "Event types for NMA A2U interface.";
  }

  grouping submitter-info {
    description "Information about who submitted the intent.";
    leaf type {
      type enumeration {
        enum user { description "Human user."; }
        enum system { description "OSS/BSS system."; }
        enum agent { description "Another agent (for future A2A)."; }
      }
      description "Type of submitter.";
    }
    leaf id {
      type string;
      description "Identifier of the submitter.";
    }
  }
}

module ietf-nma-a2u-capabilities {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-capabilities";
  prefix nma-a2u-cap;

  import ietf-nma-a2u-common { prefix nma-a2u-common; }
  import ietf-inet-types { prefix inet; }

  organization "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "YANG data model for NMA Agent Capability discovery (Agent Card).

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  container agent-capabilities {
    config false;
    description "Agent capability discovery information.";

    leaf agent-id {
      type string;
      mandatory true;
      description "Unique identifier of the NMA.";
    }

    leaf version {
      type string;
      mandatory true;
      description "Version of the NMA implementation.";
    }

    list skills {
      key "skill-id";
      description "Skills exposed by the NMA.";

      leaf skill-id {
        type string;
        description "Unique skill identifier.";
      }

      leaf name {
        type string;
        mandatory true;
        description "Human-readable skill name.";
      }

      leaf description {
        type string;
        description "Detailed description of the skill.";
      }

      leaf input-schema {
        type union {
          type inet:uri;
          type string;
        }
        description "URI referencing a YANG module, or inline schema description.";
      }

      leaf confirmation-required {
        type boolean;
        default "false";
        description "Whether this skill requires confirmation by default.";
      }

      leaf max-autonomy-level {
        type nma-a2u-common:autonomy-level;
        mandatory true;
        description "Maximum autonomy level this skill can operate at.";
      }

      leaf-list tags {
        type string;
        description "Categorization tags for the skill.";
      }
    }

    list endpoints {
      key "name";
      description "Available API endpoints.";

      leaf name {
        type string;
        description "Endpoint name.";
      }

      leaf uri {
        type inet:uri;
        mandatory true;
        description "Endpoint URI.";
      }

      leaf-list methods {
        type string;
        description "Supported HTTP methods.";
      }
    }

    container policies {
      description "Global policies of the NMA.";

      leaf default-autonomy-level {
        type nma-a2u-common:autonomy-level;
        description "Default autonomy level for all skills.";
      }

      leaf human-in-the-loop {
        type boolean;
        default "true";
        description "Whether human-in-the-loop is globally enabled.";
      }

      leaf max-timeout-seconds {
        type uint32;
        description "Maximum timeout for task execution in seconds.";
      }
    }
  }
}

module ietf-nma-a2u-intent {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-intent";
  prefix nma-a2u-intent;

  import ietf-nma-a2u-common { prefix nma-a2u-common; }
  import ietf-yang-types { prefix yang; }

  organization "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "YANG data model for NMA Intent (dual-modal: NL and Structured).

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  container intents {
    description "Container for all intents.";

    list intent {
      key "intent-id";
      description "A submitted intent.";

      leaf intent-id {
        type string;
        description "Unique intent identifier.";
      }

      leaf mode {
        type nma-a2u-common:intent-mode;
        mandatory true;
        description "Input mode: natural-language or structured.";
      }

      container submitter {
        uses nma-a2u-common:submitter-info;
        description "Who submitted this intent.";
      }

      leaf timestamp {
        type yang:date-and-time;
        mandatory true;
        description "Intent submission timestamp.";
      }

      leaf state {
        type nma-a2u-common:task-state;
        mandatory true;
        description "Current state of the intent.";
      }

      leaf task-id {
        type leafref {
          path "/ietf-nma-a2u-tasks:tasks/task/task-id";
        }
        description "Associated task identifier.";
      }

      choice mode-choice {
        description "Mode-specific content.";
        case natural-language {
          container natural-language {
            description "Natural language intent details.";

            leaf text {
              type string;
              mandatory true;
              description "Raw natural language input.";
            }

            leaf parsed-result {
              type anydata;
              description "Internal structured representation after parsing.";
            }

            leaf confidence {
              type decimal64 {
                fraction-digits 2;
                range "0..1";
              }
              description "Parsing confidence score.";
            }

            leaf parser {
              type enumeration {
                enum llm { description "LLM-based parser."; }
                enum rule { description "Rule-based parser."; }
                enum hybrid { description "Hybrid parser."; }
              }
              description "Parser type used.";
            }
          }
        }
        case structured {
          container structured {
            description "Structured intent details.";

            leaf type {
              type nma-a2u-common:intent-type;
              mandatory true;
              description "Type of operation.";
            }

            leaf target-resource {
              type string;
              description "Target resource identifier.";
            }

            leaf constraints {
              type anydata;
              mandatory true;
              description "Domain-specific constraints. External YANG modules may define the structure.";
            }

            leaf priority {
              type uint8 {
                range "1..10";
              }
              default "5";
              description "Priority level (1=lowest, 10=highest).";
            }
          }
        }
      }

      leaf estimated-completion {
        type uint32;
        units "seconds";
        config false;
        description "Estimated time to complete in seconds.";
      }
    }
  }
}

module ietf-nma-a2u-tasks {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-tasks";
  prefix nma-a2u-task;

  import ietf-nma-a2u-common { prefix nma-a2u-common; }
  import ietf-nma-a2u-intent { prefix nma-a2u-intent; }
  import ietf-yang-types { prefix yang; }

  organization "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "YANG data model for NMA Task lifecycle management.

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  container tasks {
    config false;
    description "Container for all tasks.";

    list task {
      key "task-id";
      description "A task instantiated from an intent.";

      leaf task-id {
        type string;
        description "Unique task identifier.";
      }

      leaf parent-intent-id {
        type leafref {
          path "/nma-a2u-intent:intents/nma-a2u-intent:intent/nma-a2u-intent:intent-id";
        }
        mandatory true;
        description "The intent that spawned this task.";
      }

      leaf state {
        type nma-a2u-common:task-state;
        mandatory true;
        description "Current task state.";
      }

      leaf created-at {
        type yang:date-and-time;
        mandatory true;
        description "Task creation timestamp.";
      }

      leaf updated-at {
        type yang:date-and-time;
        mandatory true;
        description "Last state update timestamp.";
      }

      list plan {
        key "step-id";
        description "Execution plan steps.";

        leaf step-id {
          type string;
          description "Unique step identifier.";
        }

        leaf action {
          type string;
          mandatory true;
          description "Action name or API call.";
        }

        leaf target {
          type string;
          description "Target resource or component.";
        }

        leaf input-params {
          type anydata;
          description "Input parameters for this step.";
        }

        leaf status {
          type enumeration {
            enum pending { description "Step pending execution."; }
            enum running { description "Step currently executing."; }
            enum completed { description "Step completed successfully."; }
            enum failed { description "Step failed."; }
            enum skipped { description "Step skipped."; }
          }
          mandatory true;
          description "Step execution status.";
        }

        leaf observation {
          type string;
          description "Observation or output from this step.";
        }

        leaf started-at {
          type yang:date-and-time;
          description "Step start timestamp.";
        }

        leaf completed-at {
          type yang:date-and-time;
          description "Step completion timestamp.";
        }
      }

      container result {
        description "Final task result.";

        leaf success {
          type boolean;
          mandatory true;
          description "Whether the task succeeded.";
        }

        leaf summary {
          type string;
          mandatory true;
          description "Human-readable summary of the result.";
        }

        leaf-list affected-resources {
          type string;
          description "List of resources affected by this task.";
        }

        leaf output-data {
          type anydata;
          description "Structured output data.";
        }
      }

      list audit-log {
        key "log-id";
        description "Audit trail for the task.";

        leaf log-id {
          type string;
          description "Unique log entry identifier.";
        }

        leaf timestamp {
          type yang:date-and-time;
          mandatory true;
          description "Log entry timestamp.";
        }

        leaf actor {
          type string;
          mandatory true;
          description "Who performed the action (user, system, or NMA).";
        }

        leaf action {
          type string;
          mandatory true;
          description "Action performed.";
        }

        leaf details {
          type string;
          description "Additional details.";
        }
      }
    }
  }
}

module ietf-nma-a2u-confirmations {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-confirmations";
  prefix nma-a2u-confirm;

  import ietf-nma-a2u-common { prefix nma-a2u-common; }
  import ietf-nma-a2u-tasks { prefix nma-a2u-task; }
  import ietf-yang-types { prefix yang; }

  organization "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "YANG data model for NMA human-in-the-loop confirmations.

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  container confirmations {
    description "Container for all confirmations.";

    list confirmation {
      key "confirmation-id";
      description "A pending or resolved confirmation.";

      leaf confirmation-id {
        type string;
        description "Unique confirmation identifier.";
      }

      leaf task-id {
        type leafref {
          path "/nma-a2u-task:tasks/nma-a2u-task:task/nma-a2u-task:task-id";
        }
        mandatory true;
        description "Associated task.";
      }

      leaf type {
        type nma-a2u-common:confirmation-type;
        mandatory true;
        description "Type of confirmation.";
      }

      leaf priority {
        type uint8 {
          range "1..10";
        }
        default "5";
        description "Priority level.";
      }

      leaf timeout-seconds {
        type uint32;
        default "300";
        description "Timeout for user response in seconds.";
      }

      leaf context {
        type anydata;
        mandatory true;
        description "Contextual data for rendering the confirmation card.";
      }

      leaf-list allowed-actions {
        type enumeration {
          enum approve { description "Approve as-is."; }
          enum reject { description "Reject the operation."; }
          enum modify-and-approve { description "Modify parameters then approve."; }
          enum escalate-to-human { description "Escalate to human operator."; }
        }
        min-elements 1;
        description "Actions allowed for this confirmation.";
      }

      leaf status {
        type enumeration {
          enum pending { description "Awaiting resolution."; }
          enum approved { description "Approved."; }
          enum rejected { description "Rejected."; }
          enum modified { description "Modified and approved."; }
          enum expired { description "Timed out."; }
          enum escalated { description "Escalated to human."; }
        }
        default "pending";
        description "Current status.";
      }

      container resolution {
        description "Resolution details.";

        leaf action {
          type enumeration {
            enum approve;
            enum reject;
            enum modify-and-approve;
            enum escalate-to-human;
          }
          description "Chosen action.";
        }

        leaf modified-params {
          type anydata;
          description "Modified parameters if action is modify-and-approve.";
        }

        leaf resolved-by {
          type string;
          description "Who resolved this confirmation.";
        }

        leaf resolved-at {
          type yang:date-and-time;
          description "Resolution timestamp.";
        }
      }
    }
  }
}

module ietf-nma-a2u-events {
  yang-version 1.1;
  namespace "urn:ietf:params:xml:ns:yang:ietf-nma-a2u-events";
  prefix nma-a2u-event;

  import ietf-nma-a2u-common { prefix nma-a2u-common; }
  import ietf-nma-a2u-tasks { prefix nma-a2u-task; }
  import ietf-nma-a2u-confirmations { prefix nma-a2u-confirm; }
  import ietf-yang-types { prefix yang; }

  organization "IETF NMOP Working Group";
  contact
    "WG Web: https://datatracker.ietf.org/wg/nmop/
     WG List: nmop@ietf.org";
  description
    "YANG data model for NMA Event notifications.

     Copyright (c) 2026 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Revised BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  revision 2026-05-27 {
    description "Initial revision.";
    reference "RFC XXXX";
  }

  container events {
    config false;
    description "Container for all events.";

    list event {
      key "event-id";
      description "An event notification.";

      leaf event-id {
        type string;
        description "Unique event identifier.";
      }

      leaf event-type {
        type nma-a2u-common:nma-a2u-event-type;
        mandatory true;
        description "Type of event.";
      }

      leaf task-id {
        type leafref {
          path "/nma-a2u-task:tasks/nma-a2u-task:task/nma-a2u-task:task-id";
        }
        mandatory true;
        description "Associated task.";
      }

      leaf timestamp {
        type yang:date-and-time;
        mandatory true;
        description "Event timestamp.";
      }

      leaf recipient {
        type string;
        description "Intended recipient of this event.";
      }

      container payload {
        description "Event-specific payload.";

        choice event-payload {
          description "Payload based on event type.";

          case intent-receipt {
            container intent-receipt {
              leaf estimated-processing-time {
                type uint32;
                units "seconds";
                description "Estimated processing time.";
              }
              leaf accepted {
                type boolean;
                mandatory true;
                description "Whether the intent was accepted.";
              }
            }
          }

          case clarification-request {
            container clarification-request {
              leaf-list missing-fields {
                type string;
                description "Required fields that are missing.";
              }
              leaf-list ambiguous-fields {
                type string;
                description "Fields that are ambiguous.";
              }
              leaf-list questions {
                type string;
                description "Clarifying questions to ask the user.";
              }
            }
          }

          case rejection {
            container rejection {
              leaf reason-code {
                type string;
                mandatory true;
                description "Machine-readable rejection reason code.";
              }
              leaf explanation {
                type string;
                mandatory true;
                description "Human-readable explanation.";
              }
            }
          }

          case plan-generated {
            container plan-generated {
              leaf step-count {
                type uint32;
                mandatory true;
                description "Number of steps in the plan.";
              }
              leaf estimated-duration {
                type uint32;
                units "seconds";
                description "Estimated plan execution duration.";
              }
            }
          }

          case confirmation-required {
            container confirmation-required {
              leaf confirmation-id {
                type leafref {
                  path "/nma-a2u-confirm:confirmations/nma-a2u-confirm:confirmation/nma-a2u-confirm:confirmation-id";
                }
                mandatory true;
                description "Reference to the pending confirmation.";
              }
            }
          }

          case step-completed {
            container step-completed {
              leaf step-id {
                type string;
                mandatory true;
                description "Completed step identifier.";
              }
              leaf observation {
                type string;
                description "Observation from the step.";
              }
            }
          }

          case step-failed {
            container step-failed {
              leaf step-id {
                type string;
                mandatory true;
                description "Failed step identifier.";
              }
              leaf exception-type {
                type string;
                mandatory true;
                description "Type of exception.";
              }
              leaf affected-scope {
                type string;
                description "Scope affected by the failure.";
              }
              leaf-list remedial-suggestions {
                type string;
                description "Suggested remedial actions.";
              }
            }
          }

          case task-completed {
            container task-completed {
              leaf summary {
                type string;
                mandatory true;
                description "Task completion summary.";
              }
              leaf-list affected-resources {
                type string;
                description "Resources affected.";
              }
            }
          }

          case task-failed {
            container task-failed {
              leaf reason {
                type string;
                mandatory true;
                description "Failure reason.";
              }
              leaf failed-step-id {
                type string;
                description "Step that caused failure, if applicable.";
              }
            }
          }
        }
      }
    }
  }
}

{
  "agent-capabilities": {
    "agent-id": "nma-controller-beijing-01",
    "version": "1.2.0",
    "skills": [
      {
        "skill-id": "otn-service-provisioning",
        "name": "OTN Service Provisioning",
        "description": "Create, modify, delete and query OTN services",
        "input-schema": "urn:ietf:params:xml:ns:yang:ietf-trans-client-service",
        "confirmation-required": true,
        "max-autonomy-level": "L3",
        "tags": ["transport", "otn", "service"]
      },
      {
        "skill-id": "fault-diagnosis",
        "name": "Fault Diagnosis",
        "description": "Diagnose network faults and suggest remediations",
